import{_ as a,o as s,c as e,ai as n}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"把任务交代清楚","description":"一个好任务说明的五个要素，附改写前后对照和可直接套用的模板。","frontmatter":{"related":["/start/five-things-day-one","/automation/skills","/basics/safety-approvals"],"title":"把任务交代清楚","description":"一个好任务说明的五个要素，附改写前后对照和可直接套用的模板。","section":"start","order":3,"tags":["入门","提示词","沟通"],"sources":["https://docs.x.ai/grok-bot/overview","https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/approvals-security-and-privacy"],"wordCount":455,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"把任务交代清楚 | WANGXXXL"}],["meta",{"property":"og:description","content":"一个好任务说明的五个要素，附改写前后对照和可直接套用的模板。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/start/brief-tasks-clearly"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/start-brief-tasks-clearly-c9a28cb5ba.png"}],["meta",{"property":"og:image:alt","content":"把任务交代清楚 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"把任务交代清楚 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"一个好任务说明的五个要素，附改写前后对照和可直接套用的模板。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/start-brief-tasks-clearly-c9a28cb5ba.png"}],["meta",{"name":"twitter:image:alt","content":"把任务交代清楚 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/start/brief-tasks-clearly"}]]},"headers":[],"relativePath":"start/brief-tasks-clearly.md","filePath":"start/brief-tasks-clearly.md","lastUpdated":1792485206000}'),o={name:"start/brief-tasks-clearly.md"};function i(l,t,p,r,c,d){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="把任务交代清楚" tabindex="-1">把任务交代清楚 <a class="header-anchor" href="#把任务交代清楚" aria-label="Permalink to &quot;把任务交代清楚&quot;">​</a></h1><p>Bot 干得好不好，一半取决于你怎么交代。好消息是，这和给新同事布置工作是一回事，不需要学什么&quot;提示词技巧&quot;。</p><h2 id="五个要素" tabindex="-1">五个要素 <a class="header-anchor" href="#五个要素" aria-label="Permalink to &quot;五个要素&quot;">​</a></h2><ol><li><strong>要什么结果</strong>：最终交付物是什么？一份表格、一封草稿、一份带链接的清单？</li><li><strong>去哪里找</strong>：数据来源是哪个邮箱、哪个仓库、哪个网站、哪个文件？</li><li><strong>背景信息</strong>：这件事为什么做，给谁看，对方关心什么。</li><li><strong>边界</strong>：哪些事可以自己做，哪些必须停下来问我。</li><li><strong>完成标准</strong>：什么时候算做完？做到什么程度？截止时间？</li></ol><h2 id="改写前后对照" tabindex="-1">改写前后对照 <a class="header-anchor" href="#改写前后对照" aria-label="Permalink to &quot;改写前后对照&quot;">​</a></h2><p><strong>改写前：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我看看竞品最近在干嘛。</span></span></code></pre></div><p><strong>改写后：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我整理三个竞品（A、B、C）最近 30 天的公开动态。</span></span>
<span class="line"><span>来源：它们的官网更新页、官方 X 账号、公开新闻报道。</span></span>
<span class="line"><span>用途：下周一给团队开会用，大家主要关心新功能和价格调整。</span></span>
<span class="line"><span>边界：只看公开信息，不要注册账号，不要联系任何人。</span></span>
<span class="line"><span>交付：一张表，列为&quot;竞品 / 日期 / 动态 / 来源链接 / 对我们的影响（一句话）&quot;；</span></span>
<span class="line"><span>表格下面写 5 条以内的总结。今天下班前给我。</span></span>
<span class="line"><span>找不到可靠来源的信息不要写进表里，单独列在&quot;待核实&quot;里。</span></span></code></pre></div><p>第二种写法多花一分钟，但能省掉三轮来回。</p><h2 id="三个特别好用的句式" tabindex="-1">三个特别好用的句式 <a class="header-anchor" href="#三个特别好用的句式" aria-label="Permalink to &quot;三个特别好用的句式&quot;">​</a></h2><ul><li><strong>&quot;先给我看，再动手&quot;</strong>：适合任何有后果的操作。<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先列出你打算修改的内容和理由，我确认后再改。</span></span></code></pre></div></li><li><strong>&quot;分清事实和推测&quot;</strong>：适合调研和分析。<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>结果里请分开写：来源里查到的事实、你的推断、还没核实的问题。</span></span></code></pre></div></li><li><strong>&quot;做不到就直说&quot;</strong>：避免它硬凑答案。<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果数据源打不开或数据是旧的，直接告诉我，不要用旧数据代替。</span></span></code></pre></div></li></ul><div class="tip custom-block"><p class="custom-block-title">中途可以插话</p><p>Bot 在干活的时候，你可以随时发新消息补充或纠正。你的直接消息优先级高于后台工作。想让它立刻停下，就发&quot;停&quot;或&quot;Stop now&quot;。注意：停下不会撤销已经完成的动作。</p></div><div class="warning custom-block"><p class="custom-block-title">别一次塞太多</p><p>一条消息里塞五件不相关的事，结果往往每件都做得一般。相关的事放一起，不相关的分开发，或者交给不同的 Bot。</p></div><h2 id="拿到结果之后" tabindex="-1">拿到结果之后 <a class="header-anchor" href="#拿到结果之后" aria-label="Permalink to &quot;拿到结果之后&quot;">​</a></h2><ul><li>让它在原文件上改，而不是每次生成一份新的，避免版本混乱。</li><li>觉得某个要求以后都适用，就加一句&quot;以后都这样，请记住&quot;。</li><li>同一种任务做顺了，就可以考虑把它存成技能。</li></ul>`,16)])])}const u=a(o,[["render",i]]);export{h as __pageData,u as default};
